package com.nvv.mediadata.appimport androidx.compose.runtime.Composableimport androidx.navigation.NavHostControllerimport androidx.navigation.compose.NavHostimport androidx.navigation.compose.composableimport com.nvv.mediadata.data.model.destination.Destinationimport com.nvv.mediadata.view.profile.ProfileView@Composablefun AppNavHost(	navController: NavHostController,	startDestination: Destination,) {	NavHost(		navController,		startDestination = startDestination.route	) {		Destination.entries.forEach { destination ->			composable(destination.route) {				when (destination) {					Destination.HOME -> {}					Destination.MOVIE -> {}					Destination.TV -> {}					Destination.PROFILE -> ProfileView()				}			}		}	}}